import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { MemoryRouter } from "react-router-dom";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { isUiState, type UiState } from "./types";

// What the Rust side really emits, generated by its own test (recorder/tests/controller_tests.rs).
const contract = JSON.parse(readFileSync(join(__dirname, "../../../desktop/contract/ui-state.json"), "utf8")) as Record<string, UiState>;

const bridge = vi.hoisted(() => ({
  state: vi.fn(), start: vi.fn(), stop: vi.fn(), retry: vi.fn(), discard: vi.fn(), dismiss: vi.fn(),
  settings: vi.fn(), saveSettings: vi.fn(), ensureBackend: vi.fn(),
}));
vi.mock("./bridge", () => ({ desktop: bridge, isDesktop: () => true, onChanged: () => Promise.resolve(() => undefined) }));

import { RecordCard } from "./RecordCard";
import { RecorderProvider } from "./useRecorder";
import { RecorderBar } from "./RecorderBar";

function show(state: UiState, ui = <RecordCard />) {
  bridge.state.mockResolvedValue(state);
  return render(<QueryClientProvider client={new QueryClient()}><MemoryRouter><RecorderProvider>{ui}</RecorderProvider></MemoryRouter></QueryClientProvider>);
}
beforeEach(() => { Object.values(bridge).forEach((f) => f.mockReset().mockResolvedValue(undefined)); });

describe("contract with the Rust side", () => {
  it("every state the Rust golden file contains satisfies the TypeScript contract", () => {
    expect(Object.keys(contract).sort()).toEqual(["done", "idle", "needs_attention", "recording", "uploading"]);
    for (const [name, s] of Object.entries(contract)) expect(isUiState(s), name).toBe(true);
  });
  it("rejects shapes that drifted", () => {
    const bad = { ...contract.recording!, phase: "paused" };
    expect(isUiState(bad)).toBe(false);
    const { pending: _p, ...missing } = contract.idle!;
    expect(isUiState(missing)).toBe(false);
    expect(isUiState({ ...contract.idle!, extra: 1 })).toBe(false);
  });
});

describe("RecordCard", () => {
  it("idle: starts a recording with the typed title", async () => {
    show(contract.idle!);
    await userEvent.type(await screen.findByLabelText("Rekam rapat sekarang"), "Rapat vendor");
    await userEvent.click(screen.getByRole("button", { name: /Mulai merekam/ }));
    expect(bridge.start).toHaveBeenCalledWith("Rapat vendor");
  });

  it("idle: reminds the user to tell participants they are being recorded", async () => {
    show(contract.idle!);
    expect(await screen.findByText(/tahu bahwa rapat direkam/)).toBeInTheDocument();
  });

  it("recording: shows the clock, labelled meters, and says out loud when a source has a problem", async () => {
    show(contract.recording!);
    expect(await screen.findByText("Sedang merekam")).toBeInTheDocument();
    expect(screen.getByLabelText("Lama rekaman")).toHaveTextContent("00:00:12");
    const mic = screen.getByRole("meter", { name: "Level Mikrofon" });
    expect(mic).toHaveAttribute("aria-valuenow", "40");
    expect(screen.getByText("Terdengar")).toBeInTheDocument(); // text, not just colour
    expect(screen.getAllByText(/Mencoba tersambung lagi/).length).toBeGreaterThan(0); // the reconnecting speaker source
  });

  it("recording: stopping needs a confirmation, and 'continue' does not stop", async () => {
    show(contract.recording!);
    await userEvent.click(await screen.findByRole("button", { name: /Hentikan rekaman/ }));
    const dialog = await screen.findByRole("dialog", { name: "Hentikan rekaman?" });
    await userEvent.click(within(dialog).getByRole("button", { name: "Lanjut merekam" }));
    expect(bridge.stop).not.toHaveBeenCalled();
    await userEvent.click(screen.getByRole("button", { name: /Hentikan rekaman/ }));
    await userEvent.click(within(await screen.findByRole("dialog")).getByRole("button", { name: /^Hentikan$/ }));
    await waitFor(() => expect(bridge.stop).toHaveBeenCalledTimes(1));
  });

  it("uploading: shows the step and a real progress bar", async () => {
    show(contract.uploading!);
    expect(await screen.findByText(/Mengunggah mikrofon… 42%/)).toBeInTheDocument();
    expect(screen.getByRole("progressbar")).toHaveAttribute("aria-valuenow", "42");
    expect(screen.getByText(/sudah aman di komputer ini/)).toBeInTheDocument();
  });

  it("done: links straight to the new meeting", async () => {
    show(contract.done!);
    expect(await screen.findByRole("link", { name: "Buka rapat" })).toHaveAttribute("href", "/rapat/abc123");
    await userEvent.click(screen.getByRole("button", { name: "Tutup" }));
    expect(bridge.dismiss).toHaveBeenCalled();
  });

  it("needs attention: explains, reassures the audio is safe, and retries the very same folder", async () => {
    show(contract.needs_attention!);
    expect(await screen.findByRole("alert")).toHaveTextContent("tersimpan, tetapi belum terunggah");
    expect(screen.getByText("server tidak terjangkau")).toBeInTheDocument();
    expect(screen.getByText(/Mikrofon: tidak ada mikrofon yang aktif/)).toBeInTheDocument();
    await userEvent.click(screen.getByRole("button", { name: /Coba unggah lagi/ }));
    expect(bridge.retry).toHaveBeenCalledWith("/rec/rapat-1");
  });

  it("pending: flags a crashed recording, uploads it, and deletes only after confirmation", async () => {
    show(contract.needs_attention!);
    expect(await screen.findByText(/Terhenti mendadak, sudah dipulihkan/)).toBeInTheDocument();
    await userEvent.click(screen.getByRole("button", { name: "Unggah" }));
    expect(bridge.retry).toHaveBeenCalledWith("/rec/rapat-1");
    await userEvent.click(screen.getByRole("button", { name: "Hapus rekaman Rapat vendor" }));
    expect(bridge.discard).not.toHaveBeenCalled();
    await userEvent.click(within(await screen.findByRole("dialog")).getByRole("button", { name: "Hapus permanen" }));
    expect(bridge.discard).toHaveBeenCalledWith("/rec/rapat-1");
  });

  it("surfaces a start failure instead of failing silently", async () => {
    bridge.start.mockRejectedValue(new Error("tidak ada sumber audio yang bisa direkam"));
    show(contract.idle!);
    await userEvent.click(await screen.findByRole("button", { name: /Mulai merekam/ }));
    await waitFor(() => expect(bridge.start).toHaveBeenCalled());
  });
});

describe("RecorderBar (global indicator)", () => {
  it("appears only while recording, on every page", async () => {
    const { unmount } = show(contract.idle!, <RecorderBar />);
    await waitFor(() => expect(bridge.state).toHaveBeenCalled());
    expect(screen.queryByRole("status")).toBeNull();
    unmount();
    show(contract.recording!, <RecorderBar />);
    const bar = await screen.findByRole("status");
    expect(bar).toHaveTextContent("Merekam");
    expect(bar).toHaveTextContent("00:00:12");
    expect(bar).toHaveTextContent("Audio komputer: Perangkat terputus"); // trouble is visible app-wide
  });
});
